namespace Terra.Api.Logistics;

/// <summary>
/// Server port of engine/logistics/simulator.js. The random-call order, rounding and sorting
/// match the JavaScript exactly, so a given seed and start time produce the same network
/// (verified by the parity test against a fixture generated by the browser engine).
/// </summary>
public sealed class LogisticsSimulator
{
    private const double H = 3_600_000;
    private static readonly Dictionary<string, double> SlackH = new() { ["road"] = 3, ["air"] = 8, ["sea"] = 36 };
    private static readonly Dictionary<string, double> PriorityCost = new() { ["Standard"] = 1, ["Express"] = 1.35, ["Critical"] = 1.8 };
    private static readonly string[] Warehouses = ["EFD", "ACR", "YTL"];
    private static readonly string[] ExceptionReasons = ["Damaged packaging", "Address unknown", "Documents missing"];

    private readonly Rng _rng;
    private readonly Dictionary<long, Bucket> _buckets = new();
    private readonly List<LogisticsEvent> _events = new();
    private readonly HashSet<string> _dirty = new();
    private bool _warming;
    private int _seq = 240_000;
    private readonly object _gate = new();

    public double Time { get; private set; }
    public List<Shipment> Shipments { get; private set; } = new();
    public Dictionary<string, double> Fleet { get; } = new() { ["road"] = 1, ["air"] = 1, ["sea"] = 1 };
    public double GreenFactor { get; set; } = 1;
    public event Action<LogisticsEvent>? EventRaised;

    public LogisticsSimulator(uint seed, double nowMs, double warmupHours = 72)
    {
        _rng = new Rng(seed);
        Time = nowMs - warmupHours * H;
        _warming = true;
        Advance(warmupHours * 60, 5);
        _warming = false;
    }

    /// <summary>Thread-safe access for the API (the background service ticks concurrently).</summary>
    public T Read<T>(Func<LogisticsSimulator, T> read)
    {
        lock (_gate) return read(this);
    }

    public void Tick(double realSeconds, double speed)
    {
        lock (_gate) Advance(realSeconds * speed, 1);
    }

    /// <summary>Ids changed since the last call (for incremental persistence to SQL).</summary>
    public List<Shipment> TakeDirty()
    {
        lock (_gate)
        {
            var list = Shipments.Where(s => _dirty.Contains(s.Id)).ToList();
            _dirty.Clear();
            return list;
        }
    }

    public void Advance(double minutes, double step = 1)
    {
        var left = minutes;
        while (left > 0)
        {
            var dt = Math.Min(step, left);
            left -= dt;
            Time += dt * 60_000;
            StepOnce(dt);
        }
    }

    private void Emit(string type, Shipment s, string message, string severity = "info")
    {
        var e = new LogisticsEvent($"{type}-{s.Id}-{Time}", Time, type, s.Id, s.Mode, message, severity);
        _events.Add(e);
        if (_events.Count > 250) _events.RemoveAt(0);
        if (!_warming) EventRaised?.Invoke(e);
    }

    private Bucket GetBucket(double t)
    {
        var k = (long)Math.Floor(t / H);
        if (!_buckets.TryGetValue(k, out var b))
        {
            b = new Bucket { T = k * H };
            _buckets[k] = b;
            foreach (var old in _buckets.Keys.Where(o => o < k - 24 * 8).ToList()) _buckets.Remove(old);
        }
        return b;
    }

    private void Create(string mode)
    {
        var r = _rng;
        var dest = r.Pick(Catalog.DestinationsFor(mode));
        var origin = mode == "road" ? r.Pick(Warehouses) : mode == "air" ? "BNEC" : "PBNE";
        var priority = r.Chance(0.07) ? "Critical" : r.Chance(0.26) ? "Express" : "Standard";
        var weightKg = Rng.JsRound(mode == "sea" ? r.Range(4_000, 26_000) : mode == "air" ? r.Range(40, 2_400) : r.Range(80, 12_000));
        var unitType = mode == "sea" ? "TEU" : mode == "air" ? "ULD" : "pallets";
        var units = (int)Math.Max(1, Math.Ceiling(weightKg / (mode == "sea" ? 14_000 : mode == "air" ? 1_000 : 500)));
        var speedFactor = priority == "Critical" ? 0.85 : priority == "Express" ? 0.92 : 1;
        var transitH = (dest.Km / Catalog.SpeedKmh[mode] + Catalog.HandlingH[mode]) * speedFactor;
        var departAt = Time + r.Range(0.3, mode == "sea" ? 18 : 5) * H;
        var etaAt = departAt + transitH * H;
        var slaAt = etaAt + SlackH[mode] * (priority == "Critical" ? 0.4 : 1) * H;
        var tkm = weightKg / 1000 * dest.Km;
        var s = new Shipment
        {
            Id = $"TRA-{++_seq}",
            Mode = mode,
            Origin = origin,
            Destination = dest.Id,
            DestinationName = dest.Name,
            Carrier = r.Pick(Catalog.Carriers[mode]),
            Customer = r.Pick(Catalog.Customers),
            Priority = priority,
            WeightKg = weightKg,
            Units = units,
            UnitType = unitType,
            DistanceKm = dest.Km,
            CreatedAt = Time,
            DepartAt = departAt,
            EtaAt = etaAt,
            SlaAt = slaAt,
            Status = "Booked",
            CostAud = Rng.JsRound((Catalog.FixedAud[mode] + tkm * Catalog.RateAudTkm[mode]) * PriorityCost[priority]),
            Co2Kg = Rng.JsRound(tkm * Catalog.Emissions[mode] * GreenFactor * 10) / 10,
        };
        Shipments.Add(s);
        _dirty.Add(s.Id);
        GetBucket(Time).Created[mode]++;
    }

    private void StepOnce(double dtMin)
    {
        var r = _rng;
        foreach (var mode in Catalog.Modes)
        {
            var rate = Catalog.SpawnPerHour[mode] * Fleet[mode] * dtMin / 60;
            var n = (int)Math.Floor(rate);
            if (r.Next() < rate - n) n++;
            var hour = DateTimeOffset.FromUnixTimeMilliseconds((long)Math.Floor(Time)).UtcDateTime.Hour + 10;
            if ((hour % 24 < 6 || hour % 24 > 21) && r.Next() < 0.6) n = 0;
            for (var i = 0; i < n; i++) Create(mode);
        }

        foreach (var s in Shipments)
        {
            if (s.Status == "Delivered") continue;
            if (s.Status == "Booked")
            {
                if (Time >= s.DepartAt)
                {
                    s.Status = "In Transit";
                    _dirty.Add(s.Id);
                }
                else continue;
            }
            if (s.Status == "Exception")
            {
                if (Time >= (s.DelayUntil ?? 0))
                {
                    s.Status = "In Transit";
                    _dirty.Add(s.Id);
                    Emit("resolved", s, $"{s.Id} exception resolved, back in transit");
                }
                continue;
            }
            if (s.Status == "Delayed" && Time >= (s.DelayUntil ?? 0)) s.Status = "In Transit";
            if (s.Status == "In Transit")
            {
                if (r.Next() < Catalog.DelayPerHour[s.Mode] * dtMin / 60)
                {
                    var hours = s.Mode == "sea" ? r.Range(10, 60) : s.Mode == "air" ? r.Range(2, 12) : r.Range(0.5, 5);
                    s.Status = "Delayed";
                    s.DelayReason = r.Pick(Catalog.DelayReasons[s.Mode]);
                    s.DelayUntil = Time + hours * H;
                    s.EtaAt += hours * H;
                    GetBucket(Time).Delays++;
                    _dirty.Add(s.Id);
                    Emit("delayed", s, $"{s.Id} to {s.DestinationName} delayed {Rng.JsRound(hours)} h: {s.DelayReason}", s.Priority == "Critical" ? "critical" : "warning");
                }
                else if (r.Next() < 0.0006 * dtMin / 60)
                {
                    s.Status = "Exception";
                    s.DelayReason = r.Pick(ExceptionReasons);
                    s.DelayUntil = Time + r.Range(6, 24) * H;
                    s.EtaAt = Math.Max(s.EtaAt, s.DelayUntil.Value + 2 * H);
                    _dirty.Add(s.Id);
                    Emit("exception", s, $"{s.Id} exception: {s.DelayReason}", "critical");
                }
            }
            s.Progress = Math.Min(1, Math.Max(0, (Time - s.DepartAt) / Math.Max(1, s.EtaAt - s.DepartAt)));
            if (s.Status == "In Transit" && s.Mode != "road" && s.Progress > 0.93) s.Status = "At Hub";
            if ((s.Status == "In Transit" || s.Status == "At Hub") && Time >= s.EtaAt)
            {
                s.Status = "Delivered";
                s.DeliveredAt = Time;
                s.Progress = 1;
                s.OnTime = s.DeliveredAt <= s.SlaAt;
                _dirty.Add(s.Id);
                var b = GetBucket(Time);
                b.Delivered[s.Mode]++;
                if (s.OnTime == true) b.OnTime++;
                else b.Late++;
                b.Co2 += s.Co2Kg;
                b.Revenue += s.CostAud;
                if (s.OnTime != true && s.Priority != "Standard") Emit("late", s, $"{s.Id} ({s.Priority}) delivered late to {s.DestinationName}", "warning");
            }
        }

        if (Shipments.Count > 2_500)
        {
            var cutoff = Time - 7 * 24 * H;
            Shipments = Shipments.Where(s => s.Status != "Delivered" || (s.DeliveredAt ?? 0) > cutoff).ToList();
        }
    }

    public Shipment? Expedite(string id)
    {
        lock (_gate)
        {
            var s = Shipments.FirstOrDefault(x => x.Id == id);
            if (s is null || s.Status == "Delivered") return null;
            if (!s.Expedited)
            {
                s.Expedited = true;
                s.Priority = s.Priority == "Standard" ? "Express" : "Critical";
                var remaining = Math.Max(0, s.EtaAt - Time);
                s.EtaAt = Time + remaining * 0.7;
                s.CostAud = Rng.JsRound(s.CostAud * 1.25);
                if (s.Status == "Delayed") s.DelayUntil = Math.Min(s.DelayUntil ?? Time, Time + H);
                _dirty.Add(s.Id);
                Emit("expedited", s, $"{s.Id} expedited — new ETA brought forward");
            }
            return s;
        }
    }

    public Snapshot Snapshot()
    {
        lock (_gate) return BuildSnapshot();
    }

    private Snapshot BuildSnapshot()
    {
        var now = Time;
        var since = now - 24 * H;
        var delivered = Shipments.Where(s => s.DeliveredAt is { } d && d > since).ToList();
        var active = Shipments.Where(s => s.Status != "Delivered").ToList();
        var onTime = delivered.Count(s => s.OnTime == true);
        List<Shipment> ByMode(List<Shipment> list, string mode) => list.Where(s => s.Mode == mode).ToList();
        double AvgTransit(string mode)
        {
            var list = ByMode(delivered, mode);
            return list.Count == 0 ? 0 : list.Aggregate(0.0, (sum, s) => sum + ((s.DeliveredAt ?? 0) - s.DepartAt) / H) / list.Count;
        }
        var tonneKm = delivered.Aggregate(0.0, (sum, s) => sum + s.WeightKg / 1000 * s.DistanceKm);
        var co2 = delivered.Aggregate(0.0, (sum, s) => sum + s.Co2Kg);
        var revenue = delivered.Aggregate(0.0, (sum, s) => sum + s.CostAud);
        var weight = delivered.Aggregate(0.0, (sum, s) => sum + s.WeightKg);
        var capacity = new Dictionary<string, double> { ["road"] = 110 * Fleet["road"], ["air"] = 50 * Fleet["air"], ["sea"] = 100 * Fleet["sea"] };
        int InTransit(string mode) => active.Count(s => s.Mode == mode && s.Status != "Booked");

        var series = new List<SeriesPoint>();
        var nowKey = (long)Math.Floor(now / H);
        for (var k = nowKey - 47; k <= nowKey; k++)
        {
            _buckets.TryGetValue(k, out var b);
            series.Add(new SeriesPoint(
                k * H,
                b?.Delivered["road"] ?? 0, b?.Delivered["air"] ?? 0, b?.Delivered["sea"] ?? 0,
                b?.OnTime ?? 0, b?.Late ?? 0,
                Rng.JsRound(b?.Co2 ?? 0), Rng.JsRound(b?.Revenue ?? 0),
                (b?.Created["road"] ?? 0) + (b?.Created["air"] ?? 0) + (b?.Created["sea"] ?? 0)));
        }

        // Insertion-ordered grouping to match JavaScript Map iteration.
        var recent = Shipments.Where(x => x.CreatedAt > now - 72 * H).ToList();
        var laneOrder = new List<string>();
        var lanes = new Dictionary<string, (string Origin, string Dest, string Mode, int Volume, int Delivered, int OnTime, double DelayH, double Revenue, double Co2)>();
        foreach (var s in recent)
        {
            var key = $"{s.Origin}→{s.Destination}";
            if (!lanes.TryGetValue(key, out var l))
            {
                laneOrder.Add(key);
                l = (s.Origin, s.DestinationName, s.Mode, 0, 0, 0, 0, 0, 0);
            }
            l.Volume++;
            l.Revenue += s.CostAud;
            l.Co2 += s.Co2Kg;
            if (s.DeliveredAt is { } d)
            {
                l.Delivered++;
                if (s.OnTime == true) l.OnTime++;
                l.DelayH += Math.Max(0, (d - s.SlaAt) / H);
            }
            lanes[key] = l;
        }
        var laneRows = laneOrder
            .Select(k => (k, l: lanes[k]))
            .Select(x => new LaneRow(x.k, x.l.Origin, x.l.Dest, x.l.Mode, x.l.Volume, x.l.Delivered, x.l.OnTime, x.l.DelayH, x.l.Revenue, x.l.Co2,
                x.l.Delivered > 0 ? (double)x.l.OnTime / x.l.Delivered : null, x.l.Delivered > 0 ? x.l.DelayH / x.l.Delivered : 0))
            .OrderByDescending(l => l.Volume) // stable, like Array.prototype.sort
            .ToList();

        var carrierOrder = new List<string>();
        var carriers = new Dictionary<string, (string Mode, int Volume, int Delivered, int OnTime, double Cost, double Tkm, double Co2)>();
        foreach (var s in recent)
        {
            if (!carriers.TryGetValue(s.Carrier, out var c))
            {
                carrierOrder.Add(s.Carrier);
                c = (s.Mode, 0, 0, 0, 0, 0, 0);
            }
            c.Volume++;
            c.Cost += s.CostAud;
            c.Tkm += s.WeightKg / 1000 * s.DistanceKm;
            c.Co2 += s.Co2Kg;
            if (s.DeliveredAt is not null)
            {
                c.Delivered++;
                if (s.OnTime == true) c.OnTime++;
            }
            carriers[s.Carrier] = c;
        }
        var carrierRows = carrierOrder.Select(name =>
        {
            var c = carriers[name];
            return new CarrierRow(name, c.Mode, c.Volume, c.Delivered, c.OnTime, c.Cost, c.Tkm, c.Co2,
                c.Delivered > 0 ? (double)c.OnTime / c.Delivered : null, c.Tkm > 0 ? c.Cost / c.Tkm : 0, c.Tkm > 0 ? c.Co2 / c.Tkm : 0);
        }).ToList();

        var hubs = Catalog.Hubs.Select((h, i) =>
        {
            var wave = Math.Sin(now / (H * 9) + i * 1.7) * 0.14 + Math.Sin(now / (H * 2.3) + i) * 0.05;
            var pressure = active.Count(s => s.Origin == h.Id) / (h.Kind == "warehouse" ? 120.0 : 30.0);
            var occupancy = Math.Max(0.12, Math.Min(0.99, 0.52 + wave + Math.Min(0.3, pressure * 0.15)));
            var doors = h.Kind == "warehouse" ? 24 : 10;
            return new HubRow(h.Id, h.Name, h.Kind, h.Lon, h.Lat, h.Capacity, h.Unit, occupancy, (int)Rng.JsRound(occupancy * doors), doors);
        }).ToList();

        var departures = Shipments
            .Where(s => s.Status == "Booked" && s.DepartAt < now + 12 * H)
            .OrderBy(s => s.DepartAt)
            .Take(24)
            .ToList();

        var modeStats = Catalog.Modes.ToDictionary(m => m, m =>
        {
            var list = ByMode(delivered, m);
            return new ModeStat(
                list.Count,
                list.Aggregate(0.0, (sum, x) => sum + x.WeightKg / 1000 * x.DistanceKm),
                list.Aggregate(0.0, (sum, x) => sum + x.Co2Kg),
                list.Aggregate(0.0, (sum, x) => sum + x.CostAud),
                list.Count(x => x.OnTime == true));
        });

        var kpis = new Kpis(
            delivered.Count > 0 ? (double)onTime / delivered.Count : 1,
            delivered.Count,
            active.Count(s => s.Status is "In Transit" or "At Hub"),
            active.Count(s => s.Status == "Booked"),
            active.Count(s => s.Status == "Delayed"),
            active.Count(s => s.Status == "Exception"),
            revenue,
            Rng.JsRound(co2),
            tonneKm > 0 ? co2 / tonneKm : 0,
            weight > 0 ? revenue / weight : 0,
            new ModeTriple(AvgTransit("road"), AvgTransit("air"), AvgTransit("sea")),
            new ModeTriple(
                Math.Min(1, InTransit("road") / capacity["road"]),
                Math.Min(1, InTransit("air") / capacity["air"]),
                Math.Min(1, InTransit("sea") / capacity["sea"])));

        var alerts = Enumerable.Reverse(_events.Skip(Math.Max(0, _events.Count - 30))).ToList();
        return new Snapshot(now, kpis,
            new Dictionary<string, int> { ["road"] = ByMode(delivered, "road").Count, ["air"] = ByMode(delivered, "air").Count, ["sea"] = ByMode(delivered, "sea").Count },
            modeStats, series, laneRows, carrierRows, hubs, departures, alerts);
    }
}
